  const bool tandbtogether=true, largemassexp=false;
  auto kinstructure = two * zb(j5, j3) * zb(j3, j1) * za(j2, j4) / s45;
  std::complex<double> A53_res = czip;

  if (tandbtogether) {
    A53_res = -kinstructure * L1(-s12, -s45) / two / s45;
  }

  if (mtsq == 0.0) {
    A53_res = kinstructure * L1(-s12, -s45) / two / s45;
